import { PatternGenerator } from './patternGenerator';
import { JevAdapter } from '../ai/jevAdapter';
import { Pattern, PlayerState, GameSession, PatternType } from '../types';
import { io, Socket } from 'socket.io-client';

export class GameEngine {
  private patternGenerator: PatternGenerator;
  private jevAdapter: JevAdapter | null;
  private currentSession: GameSession | null = null;
  private localMode: boolean = true;
  private socket: Socket | null = null;
  private serverUrl: string = 'http://localhost:3001';

  constructor(jevApiKey?: string) {
    this.patternGenerator = new PatternGenerator();
    this.jevAdapter = jevApiKey ? new JevAdapter(jevApiKey) : null;
  }

  async startLocalGame(playerId: string): Promise<GameSession> {
    const playerState: PlayerState = {
      id: playerId,
      score: 0,
      level: 1,
      patternsSolved: 0,
      patternsFailed: 0,
      strengths: {
        numeric: 0.5,
        visual: 0.5,
        logical: 0.5,
        sequence: 0.5,
        geometric: 0.5
      },
      weaknesses: {
        numeric: 0.5,
        visual: 0.5,
        logical: 0.5,
        sequence: 0.5,
        geometric: 0.5
      },
      averageTime: 0,
      streak: 0
    };

    this.currentSession = {
      id: `session-${Date.now()}`,
      mode: 'local',
      players: [playerState],
      currentPattern: null,
      status: 'active',
      startTime: Date.now()
    };

    this.localMode = true;
    await this.generateNextPattern();
    return this.currentSession;
  }

  async startOnlineGame(playerId: string, playerName: string): Promise<GameSession> {
    // Connect to WebSocket server
    this.socket = io(this.serverUrl);
    this.localMode = false;

    return new Promise((resolve, reject) => {
      this.socket!.on('connect', () => {
        console.log('Connected to server');

        // Join as player
        this.socket!.emit('player:join', {
          playerId,
          playerName,
          userAgent: navigator.userAgent
        });

        this.socket!.on('player:joined', (data) => {
          if (data.success) {
            // Create a temporary session until we join a game
            this.currentSession = {
              id: 'waiting-for-game',
              mode: 'online',
              players: [{
                id: playerId,
                name: playerName,
                score: 0,
                level: 1,
                patternsSolved: 0,
                patternsFailed: 0,
                strengths: { numeric: 0.5, visual: 0.5, logical: 0.5, sequence: 0.5, geometric: 0.5 },
                weaknesses: { numeric: 0.5, visual: 0.5, logical: 0.5, sequence: 0.5, geometric: 0.5 },
                averageTime: 0,
                streak: 0
              }],
              currentPattern: null,
              status: 'waiting',
              startTime: Date.now()
            };
            resolve(this.currentSession);
          }
        });

        this.socket!.on('error', (error) => {
          reject(error);
        });
      });

      this.socket!.on('disconnect', () => {
        console.log('Disconnected from server');
      });

      this.socket!.on('connect_error', (error) => {
        console.error('Connection error:', error);
        reject(error);
      });
    });
  }

  async createMultiplayerGame(maxPlayers: number = 4, gameMode: string = 'competitive'): Promise<string> {
    if (!this.socket) throw new Error('Not connected to server');

    return new Promise((resolve, reject) => {
      this.socket!.emit('game:create', {
        maxPlayers,
        gameMode
      });

      this.socket!.on('game:created', (data) => {
        this.currentSession!.id = data.gameId;
        resolve(data.gameId);
      });

      this.socket!.on('error', (error) => {
        reject(error);
      });
    });
  }

  async joinMultiplayerGame(gameId: string): Promise<void> {
    if (!this.socket) throw new Error('Not connected to server');

    return new Promise((resolve, reject) => {
      this.socket!.emit('game:join', { gameId });

      this.socket!.on('game:player_joined', (data) => {
        this.currentSession = {
          id: data.game.id,
          mode: 'online',
          players: data.game.players,
          currentPattern: null,
          status: data.game.status,
          startTime: data.game.createdAt
        };
        resolve();
      });

      this.socket!.on('error', (error) => {
        reject(error);
      });
    });
  }

  async getAvailableGames(): Promise<any[]> {
    if (!this.socket) throw new Error('Not connected to server');

    return new Promise((resolve, reject) => {
      this.socket!.emit('games:list');

      this.socket!.on('games:list', (games) => {
        resolve(games);
      });

      this.socket!.on('error', (error) => {
        reject(error);
      });
    });
  }

  setupMultiplayerEventHandlers(callbacks: {
    onGameStarted?: (gameState: any) => void;
    onPlayerJoined?: (data: any) => void;
    onPlayerLeft?: (data: any) => void;
    onAnswerResult?: (data: any) => void;
    onGameEnded?: (results: any) => void;
  }): void {
    if (!this.socket) return;

    if (callbacks.onGameStarted) {
      this.socket.on('game:started', callbacks.onGameStarted);
    }

    if (callbacks.onPlayerJoined) {
      this.socket.on('game:player_joined', callbacks.onPlayerJoined);
    }

    if (callbacks.onPlayerLeft) {
      this.socket.on('game:player_left', callbacks.onPlayerLeft);
    }

    if (callbacks.onAnswerResult) {
      this.socket.on('game:answer_result', callbacks.onAnswerResult);
    }

    if (callbacks.onGameEnded) {
      this.socket.on('game:ended', callbacks.onGameEnded);
    }
  }

  async submitMultiplayerAnswer(gameId: string, answer: any, timeTaken: number): Promise<any> {
    if (!this.socket) throw new Error('Not connected to server');

    this.socket.emit('game:submit_answer', {
      gameId,
      answer,
      timeTaken
    });

    // Return a promise that resolves when we get the result
    return new Promise((resolve) => {
      const handler = (data: any) => {
        if (data.gameId === gameId) {
          this.socket?.off('game:answer_result', handler);
          resolve(data.result);
        }
      };
      this.socket?.on('game:answer_result', handler);
    });
  }

  trackAnalyticsEvent(event: string, properties: any = {}): void {
    if (this.socket) {
      this.socket.emit('analytics:event', {
        event,
        properties
      });
    }
  }

  disconnect(): void {
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
    }
  }

  getCurrentSession(): GameSession | null {
    return this.currentSession;
  }

  private async generateNextPattern(): Promise<void> {
    if (!this.currentSession) return;

    const player = this.currentSession.players[0];
    let patternType: PatternType | undefined;

    if (this.jevAdapter && !this.localMode) {
      // Use Jev to select pattern type based on player weaknesses
      patternType = await this.jevAdapter.selectPatternType(player);
    }

    const difficulty = this.calculateDifficulty(player);
    const pattern = this.patternGenerator.generatePattern(difficulty, patternType);
    this.currentSession.currentPattern = pattern;
  }

  private calculateDifficulty(player: PlayerState): number {
    // Base difficulty on player level and performance
    const baseDifficulty = player.level;
    const performanceFactor = player.patternsSolved / (player.patternsSolved + player.patternsFailed || 1);
    return Math.min(10, Math.max(1, Math.floor(baseDifficulty * performanceFactor)));
  }

  async submitAnswer(playerId: string, answer: any, timeTaken: number): Promise<{
    correct: boolean;
    score: number;
    nextPattern: Pattern | null;
    message: string;
  }> {
    if (!this.currentSession || !this.currentSession.currentPattern) {
      throw new Error('No active game session');
    }

    const pattern = this.currentSession.currentPattern;
    const player = this.currentSession.players.find(p => p.id === playerId);
    if (!player) throw new Error('Player not found');

    const correct = this.patternGenerator.validateSolution(pattern, answer);
    let score = 0;

    if (correct) {
      // Calculate score based on difficulty and time
      const timeBonus = Math.max(0, (pattern.timeLimit - timeTaken) / pattern.timeLimit);
      score = Math.round(pattern.difficulty * 10 * (1 + timeBonus));

      player.score += score;
      player.patternsSolved++;
      player.streak++;

      // Update strengths
      player.strengths[pattern.type] = Math.min(1, player.strengths[pattern.type] + 0.1);
      player.weaknesses[pattern.type] = Math.max(0, player.weaknesses[pattern.type] - 0.1);

      // Check for level up
      if (player.patternsSolved % 5 === 0) {
        player.level++;
      }
    } else {
      player.patternsFailed++;
      player.streak = 0;

      // Update weaknesses
      player.weaknesses[pattern.type] = Math.min(1, player.weaknesses[pattern.type] + 0.1);
      player.strengths[pattern.type] = Math.max(0, player.strengths[pattern.type] - 0.1);
    }

    // Update average time
    const totalTime = player.averageTime * (player.patternsSolved + player.patternsFailed - 1) + timeTaken;
    player.averageTime = totalTime / (player.patternsSolved + player.patternsFailed);

    // Use Jev to evaluate performance and adjust difficulty
    if (this.jevAdapter && !this.localMode) {
      await this.jevAdapter.evaluatePerformance(player, timeTaken);
      const shouldIncrease = await this.jevAdapter.shouldIncreaseDifficulty(player);

      if (shouldIncrease && correct) {
        player.level = Math.min(10, player.level + 1);
      }
    }

    // Generate next pattern
    await this.generateNextPattern();

    return {
      correct,
      score,
      nextPattern: this.currentSession.currentPattern,
      message: correct 
        ? `Correct! +${score} points. Streak: ${player.streak}` 
        : `Wrong! The answer was ${pattern.solution}. Try again!`
    };
  }

  async getHint(): Promise<string> {
    if (!this.currentSession || !this.currentSession.currentPattern) {
      return 'No active pattern';
    }

    if (this.jevAdapter && !this.localMode) {
      const player = this.currentSession.players[0];
      return await this.jevAdapter.generateHint(this.currentSession.currentPattern, player);
    }

    // Fallback hints
    const pattern = this.currentSession.currentPattern;
    switch (pattern.type) {
      case 'numeric': return 'Look for arithmetic progressions';
      case 'visual': return 'Find the repeating color pattern';
      case 'logical': return 'Apply the mathematical operation';
      case 'sequence': return 'Each number is the sum of the previous two';
      case 'geometric': return 'Look for rotation patterns';
      default: return 'Think about the pattern carefully';
    }
  }

  getCurrentSession(): GameSession | null {
    return this.currentSession;
  }

  endGame(): void {
    this.currentSession = null;
  }
}
